// Do not edit this file as it will be overwritten if HAMR codegen is rerun

@sig trait PreparationStateGovernor_Api {
  def id: Art.BridgeId
  def arbitrationDecision_Id : Art.PortId
  def preparationState_Id : Art.PortId
  def preparationDecision_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var preparationState: EIT_Acquisition_Session_Coordinator.PreparationState.Type = $

  def put_preparationState(value : EIT_Acquisition_Session_Coordinator.PreparationState.Type) : Unit = {
    Contract(
      Modifies(preparationState),
      Ensures(
        preparationState == value
      )
    )
    Spec {
      preparationState = value
    }

    Art.putValue(preparationState_Id, EIT_Acquisition_Session_Coordinator.PreparationState_Payload(value))
  }

  // Logika spec var representing port state for outgoing data port
  @spec var preparationDecision: EIT_Acquisition_Session_Coordinator.PreparationDecisionSnapshot = $

  def put_preparationDecision(value : EIT_Acquisition_Session_Coordinator.PreparationDecisionSnapshot) : Unit = {
    Contract(
      Modifies(preparationDecision),
      Ensures(
        preparationDecision == value
      )
    )
    Spec {
      preparationDecision = value
    }

    Art.putValue(preparationDecision_Id, EIT_Acquisition_Session_Coordinator.PreparationDecisionSnapshot_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class PreparationStateGovernor_Initialization_Api (
  val id: Art.BridgeId,
  val arbitrationDecision_Id : Art.PortId,
  val preparationState_Id : Art.PortId,
  val preparationDecision_Id : Art.PortId) extends PreparationStateGovernor_Api

@datatype class PreparationStateGovernor_Operational_Api (
  val id: Art.BridgeId,
  val arbitrationDecision_Id : Art.PortId,
  val preparationState_Id : Art.PortId,
  val preparationDecision_Id : Art.PortId) extends PreparationStateGovernor_Api {

  // Logika spec var representing port state for incoming data port
  @spec var arbitrationDecision: EIT_Acquisition_Session_Coordinator.ArbitrationDecision = $

  def get_arbitrationDecision() : Option[EIT_Acquisition_Session_Coordinator.ArbitrationDecision] = {
    Contract(
      Ensures(
        Res == Some(arbitrationDecision)
      )
    )
    val value : Option[EIT_Acquisition_Session_Coordinator.ArbitrationDecision] = Art.getValue(arbitrationDecision_Id) match {
      case Some(EIT_Acquisition_Session_Coordinator.ArbitrationDecision_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port arbitrationDecision.  Expecting 'EIT_Acquisition_Session_Coordinator.ArbitrationDecision_Payload' but received ${v}")
        None[EIT_Acquisition_Session_Coordinator.ArbitrationDecision]()
      case _ => None[EIT_Acquisition_Session_Coordinator.ArbitrationDecision]()
    }
    return value
  }
}
